import React, { useId, useLayoutEffect, useRef } from "react";

function getFocusableElements(dialog) {
  return Array.from(
    dialog.querySelectorAll(
      "a[href], button, input, select, textarea, [tabindex]"
    )
  ).filter(
    (element) =>
      !element.matches(":disabled, [disabled]") &&
      element.getAttribute("tabindex") !== "-1" &&
      !(element.tagName === "INPUT" && element.type === "hidden")
  );
}

export function Dialog({ open, onClose, title, children }) {
  const titleId = useId();
  const dialogRef = useRef(null);
  const backdropPressedRef = useRef(false);

  useLayoutEffect(() => {
    if (!open) return;

    const dialog = dialogRef.current;
    if (!dialog) return;

    const doc = dialog.ownerDocument;
    const body = doc.body;
    const previousFocus = doc.activeElement;
    const previousOverflow = body.style.overflow;
    const previousOverflowPriority =
      body.style.getPropertyPriority("overflow");

    backdropPressedRef.current = false;
    body.style.overflow = "hidden";

    const initialFocus =
      dialog.querySelector("[data-autofocus]") ||
      getFocusableElements(dialog)[0] ||
      dialog;

    initialFocus.focus();

    return () => {
      backdropPressedRef.current = false;
      body.style.setProperty(
        "overflow",
        previousOverflow,
        previousOverflowPriority
      );

      if (
        previousFocus &&
        previousFocus !== doc.body &&
        doc.contains(previousFocus) &&
        typeof previousFocus.focus === "function"
      ) {
        previousFocus.focus();
      }
    };
  }, [open]);

  function handleKeyDown(event) {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();

      if (!event.repeat) {
        onClose?.();
      }
      return;
    }

    if (event.key !== "Tab") return;

    const dialog = event.currentTarget;
    const focusableElements = getFocusableElements(dialog);

    if (focusableElements.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }

    const activeIndex = focusableElements.indexOf(
      dialog.ownerDocument.activeElement
    );
    const lastIndex = focusableElements.length - 1;
    const atBoundary = event.shiftKey
      ? activeIndex === 0
      : activeIndex === lastIndex;

    // Also handle focus on the dialog or a non-tabbable autofocus target.
    if (activeIndex === -1 || atBoundary) {
      event.preventDefault();
      focusableElements[event.shiftKey ? lastIndex : 0].focus();
    }
  }

  function handleBackdropPress(event) {
    backdropPressedRef.current = event.target === event.currentTarget;
  }

  function handleBackdropClick(event) {
    const shouldClose =
      backdropPressedRef.current && event.target === event.currentTarget;

    backdropPressedRef.current = false;

    if (shouldClose) {
      onClose?.();
    }
  }

  if (!open) return null;

  return (
    <div
      data-testid="backdrop"
      onPointerDownCapture={handleBackdropPress}
      onMouseDownCapture={handleBackdropPress}
      onClickCapture={handleBackdropClick}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
      >
        <h2 id={titleId}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
